-- Table structure for table `aff_daily_earnings`
--

DROP TABLE IF EXISTS `aff_daily_earnings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `aff_daily_earnings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `date` date NOT NULL,
  `affiliate_id` int(11) NOT NULL,
  `active_players` int(11) NOT NULL DEFAULT '0',
  `total_players` int(11) NOT NULL DEFAULT '0',
  `gross_revenue` double NOT NULL DEFAULT '0',
  `platform_fee` double NOT NULL DEFAULT '0',
  `bonus_fee` double NOT NULL DEFAULT '0',
  `cashback_fee` double NOT NULL DEFAULT '0',
  `transaction_fee` double NOT NULL DEFAULT '0',
  `admin_fee` double NOT NULL DEFAULT '0',
  `total_fee` double NOT NULL DEFAULT '0',
  `net_revenue` double NOT NULL DEFAULT '0',
  `commission_percentage` double NOT NULL DEFAULT '0',
  `commission_amount` double NOT NULL DEFAULT '0',
  `commission_from_sub_affiliates` double NOT NULL DEFAULT '0',
  `total_commission` double NOT NULL DEFAULT '0',
  `type` int(11) DEFAULT NULL,
  `paid_flag` int(11) DEFAULT NULL,
  `manual_flag` int(11) DEFAULT NULL,
  `note` text COLLATE utf8_unicode_ci,
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `commission_percentage_breakdown` text COLLATE utf8_unicode_ci,
  `adjustment_notes` text COLLATE utf8_unicode_ci,
  `total_rake` double DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `aff_daily_earnings_date` (`affiliate_id`,`date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
