INSERT INTO `cmsnews_copy1` VALUES (2,'First time fall for Macau\'s yearly gambling revenue','MACAO -- Macau has had its first brush with annual yyyrevenue decline, after a thumping series of revenue-climbing years, the BBC reported.<br />\n<br />\nIn 2014 revenue declined 2.6%, while December saw a startling decline of 30.4% when compared to the same month in 2013, the report said.<br />\n<br />\nThe revenue fall has been attributed to China\'s clampdown on corruption, the BBC said.',31,'2015-01-05 07:54:54','0','1','en',0,0,'0000-00-00 00:00:00',2,0,'2019-03-29 00:00:00','2019-03-29 23:59:59');
