  `offline_enabled` tinyint(4) NOT NULL DEFAULT '0',
  `mobile_enabled` tinyint(4) NOT NULL DEFAULT '0',
  `note` varchar(1000) COLLATE utf8_unicode_ci DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  `flag_show_in_site` int(10) unsigned NOT NULL DEFAULT '1',
  `no_cash_back` int(11) DEFAULT '0',
