  `md5_fields` varchar(32) COLLATE utf8_unicode_ci DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `auto_sync_enable` tinyint(1) NOT NULL DEFAULT '1',
  `release_date` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_game_platform_id` (`game_platform_id`),
