  `clientid` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `moduleid` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `sub_game_provider` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `flash_enabled` int(11) NOT NULL DEFAULT '1',
