  `flag_show_in_site` int(11) NOT NULL DEFAULT '0',
  `no_cash_back` int(11) DEFAULT '0',
  `void_bet` int(11) DEFAULT NULL,
  `game_order` int(11) DEFAULT NULL,
  `related_game_desc_id` int(11) DEFAULT NULL,
  `dlc_enabled` tinyint(4) NOT NULL DEFAULT '0',
  `progressive` tinyint(4) NOT NULL DEFAULT '0',
