  `offline_enabled` tinyint(4) NOT NULL DEFAULT '0',
  `mobile_enabled` tinyint(4) NOT NULL DEFAULT '0',
  `enabled_on_android` tinyint(4) NOT NULL DEFAULT '0',
  `enabled_on_ios` tinyint(4) NOT NULL DEFAULT '0',
  `flag_new_game` tinyint(4) NOT NULL DEFAULT '0',
  `html_five_enabled` tinyint(4) NOT NULL DEFAULT '0',
  `demo_link` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `md5_fields` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_on` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `action` varchar(20) COLLATE utf8_unicode_ci NOT NULL,
  `auto_sync_enable` tinyint(1) NOT NULL DEFAULT '1',
  `release_date` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=170 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
