  `flag` int(10) unsigned NOT NULL,
  `has_both_side` int(11) NOT NULL DEFAULT '1',
  `updated_at` datetime DEFAULT NULL,
  `trans_amount` double DEFAULT NULL,
  `trans_type` int(11) DEFAULT NULL,
  `win_amount` double DEFAULT NULL,
  `loss_amount` double DEFAULT NULL,
  `odds` double DEFAULT NULL,
