  `ip_address` varchar(100) DEFAULT NULL,
  `sync_index` bigint(20) DEFAULT NULL,
  `odds_type` int(11) DEFAULT NULL,
  `bet_at` datetime DEFAULT NULL,
  `md5_sum` varchar(32) DEFAULT NULL,
  `is_parlay` tinyint(1) DEFAULT '0',
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_game_logs_external_uniqueid` (`game_platform_id`,`external_uniqueid`),
