  KEY `idx_sync_index` (`sync_index`),
  KEY `index_external_uniqueid` (`external_uniqueid`),
  KEY `idx_bet_at` (`bet_at`),
  KEY `idx_md5_sum` (`md5_sum`),
  KEY `idx_updated_at` (`updated_at`),
  KEY `idx_table` (`table`)
