  `game_type` varchar(300) COLLATE utf8_unicode_ci DEFAULT NULL,
  `game_provider` varchar(300) COLLATE utf8_unicode_ci DEFAULT NULL,
  `balance` double DEFAULT NULL,
  `bet` double DEFAULT NULL,
  `status` int(11) DEFAULT NULL,
  `game_platform` varchar(300) COLLATE utf8_unicode_ci DEFAULT NULL,
  `external_uniqueid` varchar(300) COLLATE utf8_unicode_ci DEFAULT NULL,
  `response_result_id` varchar(300) COLLATE utf8_unicode_ci DEFAULT NULL,
  `bet_id` varchar(64) COLLATE utf8_unicode_ci DEFAULT NULL,
  `bundle_id` int(11) DEFAULT NULL,
  `game_result` varchar(400) COLLATE utf8_unicode_ci DEFAULT NULL,
  `currency` varchar(10) COLLATE utf8_unicode_ci DEFAULT NULL,
  `player_hand` varchar(200) COLLATE utf8_unicode_ci DEFAULT NULL,
  `table_id` varchar(200) COLLATE utf8_unicode_ci DEFAULT NULL,
  `game_id` varchar(200) COLLATE utf8_unicode_ci DEFAULT NULL,
  `lucky_num` varchar(200) COLLATE utf8_unicode_ci DEFAULT NULL,
  `game_code` varchar(200) COLLATE utf8_unicode_ci DEFAULT NULL,
  `operation_code` varchar(200) COLLATE utf8_unicode_ci DEFAULT NULL,
  `change_time` datetime DEFAULT NULL,
  `change_type` varchar(200) COLLATE utf8_unicode_ci DEFAULT NULL,
  `game_name` varchar(200) COLLATE utf8_unicode_ci DEFAULT NULL,
  `ret` double DEFAULT NULL,
  `changes` double DEFAULT NULL,
  `operator` varchar(200) COLLATE utf8_unicode_ci DEFAULT NULL,
  `jcon` double DEFAULT NULL,
  `jwin` double DEFAULT NULL,
  `platform` int(11) DEFAULT NULL,
