  `match_id` varchar(300) COLLATE utf8_unicode_ci DEFAULT NULL,
  `league_id` varchar(300) COLLATE utf8_unicode_ci DEFAULT NULL,
  `league_name` varchar(300) COLLATE utf8_unicode_ci DEFAULT NULL,
  `sport_type` int(11) DEFAULT NULL,
  `away_id` int(11) DEFAULT NULL,
  `away_id_name` varchar(300) COLLATE utf8_unicode_ci DEFAULT NULL,
  `home_id` int(11) DEFAULT NULL,
  `home_id_name` varchar(300) COLLATE utf8_unicode_ci DEFAULT NULL,
  `match_datetime` datetime DEFAULT NULL,
  `bet_type` int(11) DEFAULT NULL,
  `parlay_refno` bigint(20) DEFAULT NULL,
  `bet_team` varchar(300) COLLATE utf8_unicode_ci DEFAULT NULL,
  `balance` double DEFAULT NULL,
  `hdp` int(11) DEFAULT NULL,
  `away_hdp` int(11) DEFAULT NULL,
  `home_hdp` int(11) DEFAULT NULL,
  `odds` double DEFAULT NULL,
  `away_score` int(11) DEFAULT NULL,
  `home_score` int(11) DEFAULT NULL,
  `is_live` int(11) DEFAULT NULL,
  `ticket_status` varchar(300) COLLATE utf8_unicode_ci DEFAULT NULL,
  `stake` int(11) DEFAULT NULL,
  `winlose_amount` double DEFAULT NULL,
  `winlost_datetime` datetime DEFAULT NULL,
  `game_platform` varchar(300) COLLATE utf8_unicode_ci DEFAULT NULL,
  `external_uniqueid` varchar(300) COLLATE utf8_unicode_ci DEFAULT NULL,
  `response_result_id` varchar(300) COLLATE utf8_unicode_ci DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `odds_type` int(11) DEFAULT NULL,
  `parlay_type` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `combo_type` varchar(300) COLLATE utf8_unicode_ci DEFAULT NULL,
  `is_lucky` varchar(10) COLLATE utf8_unicode_ci DEFAULT NULL,
  `bet_tag` varchar(10) COLLATE utf8_unicode_ci DEFAULT NULL,
  `last_ball_no` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_external_uniqueid` (`external_uniqueid`),
