INSERT INTO `operator_settings_copy1` VALUES (1,'enabled_compensation','true','true = if transaction fee charge to player, false = if transaction fee not charge to player',NULL,'{\"type\":\"text\",\"default_value\":\"\"}'),(2,'max_compensation_percent','1','<=1%*amount_recevied',NULL,'{\"type\":\"text\",\"default_value\":\"\"}'),(3,'max_limit_compensation_amount','1000','max limit of compensation amount',NULL,'{\"type\":\"text\",\"default_value\":\"\"}'),(4,'previous_balance_set_amount','5','checks previous balances of player and disables those balances equal or less the set amount and not include to the computation of withdraw conditions',NULL,'{\"type\":\"text\",\"default_value\":\"\"}'),(5,'non_promo_withdraw_setting','1','withdraw condition for non promo with bet or no bet',NULL,'{\"type\":\"text\",\"default_value\":\"\"}'),(6,'email_promotion_template','email','Email Promotion Template','<p><span style=\"color: rgb(24, 55, 77); font-family: HelveticaNeueLight, HelveticaNeue-Light, \'Helvetica Neue Light\', HelveticaNeue, Helvetica, Arial, sans-serif; font-size: 16px; line-height: 24px;\">Dear [playername]</span><span style=\"color: rgb(24, 55, 77); font-family: HelveticaNeueLight, HelveticaNeue-Light, \'Helvetica Neue Light\', HelveticaNeue, Helvetica, Arial, sans-serif; font-size: 16px; line-height: 24px;\">,</span></p><div><span style=\"color: rgb(24, 55, 77); font-family: HelveticaNeueLight, HelveticaNeue-Light, \'Helvetica Neue Light\', HelveticaNeue, Helvetica, Arial, sans-serif; font-size: 16px; line-height: 24px;\"><br></span></div><div><span style=\"color: rgb(24, 55, 77); font-family: HelveticaNeueLight, HelveticaNeue-Light, \'Helvetica Neue Light\', HelveticaNeue, Helvetica, Arial, sans-serif; font-size: 16px; line-height: 24px;\">Welcome and&nbsp;</span><span style=\"color: rgb(24, 55, 77); font-family: HelveticaNeueLight, HelveticaNeue-Light, \'Helvetica Neue Light\', HelveticaNeue, Helvetica, Arial, sans-serif; font-size: 16px; line-height: 24px;\"