--
-- Table structure for table `png_game_logs`
--

DROP TABLE IF EXISTS `png_game_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `png_game_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `PlayerId` int(11) NOT NULL,
  `UserName` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `TransactionId` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `Status` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `Amount` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `Time` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `ProductGroup` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
