INSERT INTO `static_sites` VALUES (2,'default','http://www.og.local','black_and_red','sites/black_and_red',1,'','chinese','<div class=\"hidden-xs is-desktop\">\n    <a href=\"javascript: void(0);\" class=\"waves-effect btn red-bg\" onclick=\"window.location.href = window.location.protocol + \'//\' + _export_smartbackend.variables.hosts.player + \'/iframe/auth/login\'\">Login</a>\n    <a href=\"javascript: void(0);\" class=\"waves-effect btn yellow-orange-bg\" onclick=\"window.location.href = window.location.protocol + \'//\' + _export_smartbackend.variables.hosts.player + \'/player_center/iframe_register\'\">Signup</a>\n</div>\n\n<div class=\"is-mobile\">\n	<span class=\"btn-wrapper\">\n		<button class=\"login_btn dark-red-bg white\" onclick=\"window.location.href = window.location.protocol + \'//\' + _export_smartbackend.variables.hosts.player + \'/iframe/auth/login\'\">Login</button>\n		<button class=\"reg_btn\" onclick=\"window.location.href = window.location.protocol + \'//\' + _export_smartbackend.variables.hosts.player + \'/player_center/iframe_register\'\">Signup</button>\n	</span>\n</div>\n\n\n<style>\n  .is-desktop a {\n      border-radius: 5px;\n      height: 30px;\n      line-height: 0 !important;\n      text-transform: unset;\n      color: #fff !important;\n  }\n</style>','<div class=\"logged is-desktop\">\n    <ul>\n        <li class=\"user-acct-name\">\n            <a href=\"/player_center/dashboard\" class=\"youname\"><%- playerName %></a>\n            <div class=\"sub-menu\">\n                <ul>\n                    <li><a class=\"ui-btn ui-btn-logout fn-left\" href=\"/player_center/dashboard/index#accountInformation\" ><i class=\"fa fa-user-circle\" aria-hidden=\"true\"></i><%- langText.header_acct_info %></a></li>\n                    <li><a class=\"ui-btn ui-btn-logout fn-left\" href=\"<%- ui.logoutUrl %>\" target=\"<%- ui.logoutIframeName %>\"><i class=\"fa fa-power-off\" aria-hidden=\"true\"></i><%- langText.button_logout %></a></li>\n                </ul>\n            </div>\n        </li>\n        <li class=\"_player_wallet_list\">\n            <a href=\"javascript: void(0);\" class=\"_player_wallet_list_toggle\">\n                <span class=\"_player_balance_span\"><strong><%- ui.total_balance %></strong></span>\n            </a>\n        </li>\n    </ul>\n</div>\n\n<div class=\"is-mobile\">\n    <div class=\"center-align\">\n        <span class=\"player-username\">Welcome! <%- default_prefix_for_username+playerName %></span>\n        <span class=\"balance\"><span class=\"_player_balance_span\">$0</span></span>\n        <span class=\"btn-wrapper\">\n            <button class=\"login_btn dark-red-bg white\" onclick=\"window.location.href = window.location.protocol + \'//\' + _export_smartbackend.variables.hosts.player\">Dashboard</button>\n            <button class=\"reg_btn\" target=\"<%- ui.logoutIframeName %>\" onclick=\"window.location.href = \'<%- ui.logoutUrl %>/1\'\"><%- langText.button_logout %></button>\n        </span>\n    </div>\n</div>\n<iframe name=\"<%- ui.logoutIframeName %>\" id=\"<%- ui.logoutIframeName %>\" width=\"0\" height=\"0\" border=\"0\" style=\"display:none;border:0px;width:0px;height:0px;\"></iframe>\n\n<script>\n    $(\'.favoriteBtn\').css(\'pointer-events\',\'auto\');\n</script>','//player.og.local','<div id=\"<%- popupId %>\" style=\"background-color: #fff;border-radius: 10px 10px 10px 10px;box-shadow: 0 0 25px 5px #999;color: #111;display: none;padding: 10px;margin-top:20px;\">\n    <span class=\"_og_popup_close\" style=\"background-color: #2b91af;color: #fff;cursor: pointer;display: inline-block;text-align: center;text-decoration: none;border-radius: 10px 10px 10px 10px;box-shadow: none;font: bold 25px sans-serif;padding: 6px 6px 2px;position: absolute;right: -6px;top: -6px;height: 30px;width:30px\">X</span>\n    <div class=\"_og_popup_iframe_content\" ></div>\n</div>','<% _.each( game_types, function( listItem ) { %>\n	<li<% if ( listItem.active ){ %> class=\"curr\"<% } %>>\n		<a href=\"<%- playerServerUri %>/game_description/index/<%- listItem.game_platform_id %>/<%- listItem.id %>\"><%- listItem.game_type %></a>\n	</li>\n<% }); %>','<% _.each( game_descriptions, function( listItem ) { %>\n	<li class=\"product\">\n		<div class=\"product-img\"><img src=\"<%- listItem.game_image %>\" /></div>\n		<div class=\"product-name mt10\"><%= listItem.game_name %></div>\n		<div class=\"fn-clear mt10\">\n			<a class=\"fn-left ui-btn real\" href=\"<%- playerServerUri%>/iframe_module/goto_ptgame/default/<%- listItem.game_code%>/real\" data-mode=\"real\" data-code=\"<%- listItem.game_code %>\" target=\'_blank\'>进入游戏</a>\n			<% if (listItem.game_type_id !== \'7\' || listItem.offline_enabled === \'1\') { %>\n			<a class=\"fn-left ui-btn ml10 trial\" href=\"<%- playerServerUri%>/pub/goto_trial_ptgame/<%- listItem.game_code%>\" data-mode=\"trial\" data-code=\"<%- listItem.game_code %>\">免费试玩</a>\n			<% } %>\n		</div>\n	</li>\n<% }); %>','og-login-logo.png',NULL,'{\"english\":\"Smartbackend\", \"chinese\":\"智能管理后台\"}','itdesk.smartbackend','sales@tot.bet','{\"aff_analytic_code\" : \"\", \"player_analytic_code\" : \"\", \"admin_analytic_code\" : \"\", \"customer_service_code\" : \"\"}',NULL,'player','admin','aff',NULL),(4,'staging','http://www.og.local','black_and_red','sites/black_and_red',1,NULL,'chinese','<form id=\"<%- formId %>\" action=\"<%- ui.loginUrl %>\" method=\"POST\" target=\"<%- ui.loginIframeName %>\">\n<span><%- default_prefix_for_username %></span>\n<input name=\"login\" type=\"text\" class=\"ui-input fn-left J-verify\" placeholder=\"<%- langText.form_field_username %>\">\n<input name=\"password\" type=\"password\" class=\"ui-input fn-left J-verify\" placeholder=\"<%- langText.form_field_password %>\">\n<input type=\"submit\" value=\"<%- langText.button_login %>\" class=\"fn-left ui-btn ui-btn-red J-submit\">\n<a class=\"fn-left ui-btn ui-btn-brown J-regist-btn _player_register\" href=\"javascript:void(0);\"><%- langText.form_register %></a>\n<input type=\"hidden\" name=\"act\" value=\"<%- act %>\">\n</form>\n<iframe name=\"<%- ui.loginIframeName %>\" id=\"<%- ui.loginIframeName %>\" width=\"0\" height=\"0\" border=\"0\" style=\"display:none;border:0px;width:0px;height:0px;\"></iframe>','<div class=\"login-member fn-left\"><i class=\"icon icon-member\"></i><a href=\"javascript:void(0)\" class=\'_player_username\'><%- default_prefix_for_username+playerName %></a></div>\n	<div class=\"login-menu fn-left fn-clear\">\n	<a href=\"javascript:void(0)\" class=\'_player_information\'><%- langText.header_information %></a>\n	<a href=\"javascript:void(0)\" class=\'_player_deposit\'><%- langText.header_deposit %></a>\n	<a href=\"javascript:void(0)\" class=\'_player_withdrawal\'><%- langText.header_withdrawal %></a>\n	<a href=\"javascript:void(0)\" class=\'_player_memcashier\'><%- langText.header_memcashier %></a>\n	<a href=\"javascript:void(0)\" class=\'_player_report\'><%- langText.header_report %></a>\n	<a href=\"javascript:void(0)\" class=\'_player_messages\'><%- langText.header_messages %> (<%- ui.messageCount %>)</a></div>\n	<a class=\"ui-btn ui-btn-logout fn-left\" href=\"<%- ui.logoutUrl %>\" target=\"<%- ui.logoutIframeName %>\"><%- langText.button_logout %></a>\n	<iframe name=\"<%- ui.logoutIframeName %>\" id=\"<%- ui.logoutIframeName %>\" width=\"0\" height=\"0\" border=\"0\" style=\"display:none;border:0px;width:0px;height:0px;\"></iframe>','//player.og.local','<div id=\"<%- popupId %>\" style=\"background-color: #fff;border-radius: 10px 10px 10px 10px;box-shadow: 0 0 25px 5px #999;color: #111;display: none;padding: 10px;margin-top:20px;\">\n    <span class=\"_og_popup_close\" style=\"background-color: #2b91af;color: #fff;cursor: pointer;display: inline-block;text-align: center;text-decoration: none;border-radius: 10px 10px 10px 10px;box-shadow: none;font: bold 25px sans-serif;padding: 6px 6px 2px;position: absolute;right: -6px;top: -6px;height: 30px;width:30px\">X</span>\n    <div class=\"_og_popup_iframe_content\" ></div>\n</div>','<% _.each( game_types, function( listItem ) { %>\n	<li<% if ( listItem.active ){ %> class=\"curr\"<% } %>>\n		<a href=\"<%- playerServerUri %>/game_description/index/<%- listItem.game_platform_id %>/<%- listItem.id %>\"><%- listItem.game_type %></a>\n	</li>\n<% }); %>','<% _.each( game_descriptions, function( listItem ) { %>\n	<li class=\"product\">\n		<div class=\"product-img\"><img src=\"<%- listItem.game_image %>\" /></div>\n		<div class=\"product-name mt10\"><%= listItem.game_name %></div>\n		<div class=\"fn-clear mt10\">\n			<a class=\"fn-left ui-btn real\" href=\"<%- playerServerUri%>/iframe_module/goto_ptgame/default/<%- listItem.game_code%>/real\" data-mode=\"real\" data-code=\"<%- listItem.game_code %>\" target=\'_blank\'>进入游戏</a>\n			<% if (listItem.game_type_id !== \'7\' || listItem.offline_enabled === \'1\') { %>\n			<a class=\"fn-left ui-btn ml10 trial\" href=\"<%- playerServerUri%>/pub/goto_trial_ptgame/<%- listItem.game_code%>\" data-mode=\"trial\" data-code=\"<%- listItem.game_code %>\">免费试玩</a>\n			<% } %>\n		</div>\n	</li>\n<% }); %>','og-login-logo.png',NULL,'{\"english\":\"Smartbackend\", \"chinese\":\"智能管理后台\"}','itdesk.smartbackend','sales@tot.bet','{\"aff_analytic_code\" : \"\", \"player_analytic_code\" : \"\", \"admin_analytic_code\" : \"\", \"customer_service_code\" : \"\"}',NULL,NULL,NULL,NULL,NULL);
